import { IdePageHeader, IdePageContent } from '@carbon/ibm-cloud-cognitive-cdai'
import React from 'react'

import flowPicture from '../assets/img/FiletoEmail.png'
import { LayoutNav } from '../layouts/LayoutNav.jsx'

import { startPattern } from './js2java.js'

import './PatternsPage.scss'

export const FiletoEmail = () => (
  <LayoutNav>
    <IdePageHeader heading='Protocol Transformation Pattern: File to Email' />
    <IdePageContent>
      <div className='patterns'>
        <img src={flowPicture} width='1000' height='150' />
        <br /><br />
        <p>The File to Email pattern provides a simple integration solution that takes input data from a File and outputs to an Email.</p>
        <br />
        <button
          type='button'
          className='tutorial-preview__section-button  bx--btn bx--btn--sm bx--btn--primary patternbutton__start'
          onClick={() => startPattern('https://github.com/ot4i/ace-patterns/releases/download/v1.0.0/FiletoEmail.patternzip', 'com.ibm.dev.pattern.FiletoEmail', '1.0.0.0')}
        >
          Start
        </button>
      </div>
    </IdePageContent>
  </LayoutNav>
)
