/*
This javascript file is for the main patterns page which lists all the patterns and has promoted tutoroials at the top of the page.
The search capability is also in this file. It uses IdeFilter.
*/

import 'whatwg-fetch'
import {
  IdePageHeader,
  IdePageContent
} from '@carbon/ibm-cloud-cognitive-cdai'
// cp4i update
import { IdeFilter } from '@carbon/ibm-cloud-cognitive-cdai/lib/components/IdeFilter/index.js'
import React, { useState, useEffect } from 'react'
import { useHistory } from 'react-router-dom'

import { ListPanelItem } from '../components/ListPanelItem.jsx'
import SideFilterPanel from '../components/SideFilterPanel.jsx'
import { LayoutNav } from '../layouts/LayoutNav.jsx'
import repoMetadata from '../patterns_repo_metadata.json'

import './PatternsPage.scss'

const repoMetadataUrl = 'https://ot4i.github.io/ace-tutorials/v13/en/patterns_repo_metadata.json'
// Function that returns patterns for a specified version
// Setting it to v13 here:
const versionNumber = 13
const fetchPatternsOfVersions = patterns =>
  patterns.filter(pattern => {
    const iibVersions = pattern.iibVersions.split('.*')
    const fromValue = parseInt(iibVersions[0])
    const toValue = parseInt(iibVersions[1] * -1)
    return versionNumber >= fromValue && versionNumber <= toValue
  })

const PatternsListItems = ({ search, filter, handleClick, patternsData }) => {
  const patterns = (patternsData && patternsData.categories[0].patterns) || repoMetadata.categories[0].patterns.slice()

  const v13Patterns = fetchPatternsOfVersions(patterns)

  // Do the positive search
  const searchRegex = new RegExp(search, 'i')
  const searchFunc = item =>
    searchRegex.exec(item.name) !== null ||
    searchRegex.exec(item.shortDesc) !== null ||
    searchRegex.exec(item.tags) !== null ||
    searchRegex.exec(item.category) !== null

  const searchedList = v13Patterns.filter(searchFunc)

  // Now do the filtering
  const filterFunc = item => {
    let keepPattern = true
    filter.categorys.forEach(filterCat => {
      if (item.category.includes(filterCat)) keepPattern = false
    })
    filter.tags.forEach(filterTag => {
      if (item.tags.includes(filterTag)) keepPattern = false
    })
    return keepPattern
  }
  const filteredList = searchedList.filter(filterFunc)

  const listDom = []
  for (const item of filteredList) {
    const _tags = (item.tags && item.tags.split(';')) || []
    const _categories = (item.category && item.category.split(',')) || []

    listDom.push(
      <ListPanelItem
        name={item.name}
        desc={item.shortDesc}
        detailsLink={item.detailsURL}
        categories={_categories}
        tags={_tags}
        key={item.name}
        handleLinkClick={preview => handleClick(item.detailsURL, preview)}
        patternData={item}
      />
    )
  }

  return listDom
}

const searchOptions = [
  {
    label: 'Tags',
    options: []
  }
]

const initFilterOptions = () => {
  const v13Patterns = fetchPatternsOfVersions(repoMetadata.categories[0].patterns)
  const allTagOptions = []
  const allCatOptions = []
  const types = [
    'red',
    'magenta',
    'purple',
    'blue',
    'cyan',
    'teal',
    'green',
    'gray',
    'cool-gray',
    'warm-gray'
  ]
  const allTags = new Set()
  const allCats = new Set()

  for (const item of v13Patterns) {
    const tags = (item.tags && item.tags.split(';')) || []
    const categories = (item.category && item.category.split(',')) || []

    for (const tag of tags) {
      allTags.add(tag)
    }

    for (const cat of categories) {
      allCats.add(cat)
    }
  }

  for (const tag of allTags) {
    allTagOptions.push({
      type: types[Math.floor(Math.random() * types.length)],
      value: tag,
      label: tag,
      selected: true
    })
  }

  for (const cat of allCats) {
    allCatOptions.push({
      type: types[Math.floor(Math.random() * types.length)],
      value: cat,
      label: cat,
      selected: true
    })
  }

  searchOptions.push({
    label: 'Category',
    options: allCatOptions
  })
  searchOptions.push({
    label: 'Tag',
    options: allTagOptions
  })
}
initFilterOptions()

export const PatternsPage = route => {
  const history = useHistory()
  const [searchQ, setSearchQ] = useState('')
  const [filterQ, setFilterQ] = useState(BuildFiltersQuery())
  const [showFilterSideBar, setFilterSidebarShow] = useState(true)

  useEffect(() => {
    setFilterSidebarShow(showFilterSideBar)
  }, [showFilterSideBar])

  // This causes the overview of the pattern to be shown.
  const handlePatternClick = (patternDetails, preview) => {
    // console.log(`patternDetails: ${JSON.stringify(patternDetails)}  ${preview}`)
    history.push(`${patternDetails}${route.location.search}`)
  }

  const handleSearchChange = val => {
    // console.log(`  val: ${JSON.stringify(val)}`)
    if (val) {
      const valMap = val.map(item => item.value)
      // console.log(`  valMap: ${valMap}`)
      setSearchQ(`((${valMap.join(')|(')}))`)
    } else {
      setSearchQ('')
    }
  }

  function BuildFiltersQuery () {
    // Rebuild the filters for both categories and the tags
    const filterQuerys = { categorys: [], tags: [] }
    searchOptions.forEach(filterType => {
      filterType.options.forEach(item => {
        // NOTE: we are adding the list of tags we _don't_ want included
        if (!item.selected) {
          if (filterType.label === 'Category') {
            filterQuerys.categorys.push(item.value)
          } else {
            filterQuerys.tags.push(item.value)
          }
        }
      })
    })
    // console.log(` filterQuerys  ${JSON.stringify(filterQuerys)}`)
    return filterQuerys
  }

  const handleFilterChange = (filterLabel, itemName, itemIndex) => {
    // console.log(`  ${filterLabel}  ${itemName}   ${itemIndex}`)
    // Check for reset
    if (filterLabel === 'reset') {
      // Reset all the options back to selected
      searchOptions.forEach(filterType => {
        filterType.options.forEach(tag => {
          tag.selected = true
        })
      })
    } else {
      const filterToUpdate = searchOptions.find(fLabel => fLabel.label === filterLabel).options[itemIndex]
      filterToUpdate.selected = !filterToUpdate.selected
    }
    setFilterQ(BuildFiltersQuery())
  }

  // Fetches latest repo_metadata from public GitHub
  const [patternsData, setPatternsData] = useState(null)
  useEffect(() => {
    // eslint-disable-next-line no-unused-vars
    const fetchPatternsData = async () => {
      const response = await fetch(repoMetadataUrl, {
        headers: new Headers({
          Accept: 'application/vnd.github.v3+json'
        }),
        method: 'GET',
        mode: 'cors',
        credentials: 'omit' // Useful for including session ID (and, IIRC, authorization headers)
      })

      const responseData = await response.json()
      if (responseData) {
        setPatternsData(responseData)
      }
    }
    // Uncomment next line if you want to use a local dev version of repo_metadata.json
    // fetchPatternsData()
  }, [])

  return (
    <LayoutNav>
      <IdePageHeader heading='Patterns' />
      <IdePageContent>
        <div className='patterns'>
          <div className='patterns__searchFilterIconsContainer'>
            <div className='patterns__searchBar'>
              <IdeFilter
                options={[]}
                onChange={handleSearchChange}
                placeholderText='What are you looking for today?'
                searchForText='Search for'
              />
            </div>
          </div>
          <div className='pattern-filter-content-layout__container'>
            <div className='pattern-filter__sidefilterpanelContainer'>
              <SideFilterPanel
                showSideBar={showFilterSideBar}
                filterOptions={searchOptions}
                onCheckBoxChange={handleFilterChange}
              />
            </div>
            <div className='patterns-page__section'>
              <ul className='patterns__list'>
                <PatternsListItems
                  search={searchQ}
                  filter={filterQ}
                  handleClick={handlePatternClick}
                  patternsData={patternsData}
                />
              </ul>
            </div>
          </div>
        </div>
      </IdePageContent>
    </LayoutNav>
  )
}
