import './SideFilterPanel.scss'
import { Checkbox, Link, SideNav, SideNavItems } from 'carbon-components-react'
import PropTypes from 'prop-types'
import React from 'react'

function SideFilterPanel ({ showSideBar, filterOptions, onCheckBoxChange }) {
  let filterCats = []
  let filterTags = []

  filterOptions.forEach(type => {
    if (type.label === 'Category') {
      filterCats = type.options
    } else if (type.label === 'Tag') {
      filterTags = type.options
    } else {
      // type not supported
    }
  })

  // // Debug code:
  // console.log(`filter Categories:`)
  // filterCats.forEach( cat => {
  //   console.log(`  ${cat.label}  ${cat.selected}`)
  // })
  // console.log(`filter Tags:`)
  // filterTags.forEach( atag => {
  //   console.log(`  ${atag.label}  ${atag.selected}`)
  // })
  const handleResetFilters = () => {
    // Call the checkbox change fn with reset value
    onCheckBoxChange('reset', '', -1)
  }

  return (
    <div className='pattern-filter-panel'>
      <SideNav
        className={showSideBar ? 'filterSidebarContainerActive' : 'filterSidebarContainer'}
        expanded={showSideBar}
        isPersistent={showSideBar}
        aria-label='Advance filter sidebar'
      >
        <div className='resetFilterCountContainer'>
          <div>
            <Link className='pattern-filter-panel__resetLink' onClick={evt => handleResetFilters()}>
              Reset filters
            </Link>
          </div>
        </div>
        <SideNavItems className='a'>
          <div className='filterHeadings'>
            Categories
          </div>
          {
            filterCats.map((cat, index) => (
              <div className='checky-box' key={index}>
                <Checkbox
                  id={`${cat.label}-tagid`}
                  labelText={`${cat.label}`}
                  value={cat.label}
                  checked={cat.selected}
                  disabled={false}
                  onChange={() => onCheckBoxChange('Category', cat.label, index)}
                />
              </div>
            ))
          }
          <div className='filterHeadings'>
            Tags
          </div>
          {
            filterTags.map((tag, index) => (
              <div className='checky-box' key={index}>
                <Checkbox
                  id={`${tag.label}-tagid`}
                  labelText={`${tag.label}`}
                  value={tag.label}
                  checked={tag.selected}
                  disabled={false}
                  onChange={() => onCheckBoxChange('Tag', tag.label, index)}
                />
              </div>
            ))
          }
        </SideNavItems>
      </SideNav>
    </div>
  )
}

SideFilterPanel.propTypes = {
  showSideBar: PropTypes.bool,
  filterOptions: PropTypes.PropTypes.arrayOf(PropTypes.string),
  onCheckBoxChange: PropTypes.PropTypes.func
}

export default SideFilterPanel
